const item = $input.item.json;
const fields = item.fields || item.body?.fields || item.body || item;

const recordId = item.id || item.body?.id || fields.id;
const status = fields.Status || fields.status;
const ayrsharePostIds = fields.AyrsharePostIds || fields.ayrshare_post_ids || '';
const publishAt = fields.PublishAt || fields.publish_at;
const variantLinkedIn = fields.VariantLinkedIn || fields.variant_linkedin || '';
const variantX = fields.VariantX || fields.variant_x || '';
const variantInstagram = fields.VariantInstagram || fields.variant_instagram || '';
const mediaUrls = Array.isArray(fields.MediaURLs) ? fields.MediaURLs : (fields.MediaURLs ? [fields.MediaURLs] : []);
const targetPlatforms = Array.isArray(fields.TargetPlatforms) && fields.TargetPlatforms.length > 0
  ? fields.TargetPlatforms
  : ['linkedin', 'x', 'instagram'];

if (!recordId) {
  throw new Error("Missing record ID in approval trigger event.");
}

// 1. Guard check: Must be approved and have no existing Ayrshare post ID
if (status !== 'approved') {
  return {
    json: {
      skip: true,
      reason: "Record status is not 'approved' (current: " + status + ")"
    }
  };
}
if (ayrsharePostIds && ayrsharePostIds.trim().length > 0) {
  return {
    json: {
      skip: true,
      reason: "Record already has AyrsharePostIds assigned: " + ayrsharePostIds
    }
  };
}

// 2. Validate lead time (PublishAt at least MIN_SCHEDULE_LEAD_MINUTES in future)
const minLeadMinutes = parseInt($env.MIN_SCHEDULE_LEAD_MINUTES || '10', 10);
const now = new Date();
if (!publishAt) {
  return {
    json: {
      record_id: recordId,
      has_error: true,
      error_message: "Missing PublishAt timestamp for scheduled post."
    }
  };
}

const publishDate = new Date(publishAt);
const diffMinutes = (publishDate.getTime() - now.getTime()) / (1000 * 60);
if (diffMinutes < minLeadMinutes) {
  return {
    json: {
      record_id: recordId,
      has_error: true,
      error_message: "PublishAt must be at least " + minLeadMinutes + " minutes in the future (lead: " + Math.round(diffMinutes) + " min)."
    }
  };
}

// Map platforms to Ayrshare format (Ayrshare uses 'twitter' for X)
const ayrPlatforms = targetPlatforms.map(p => (p === 'x' ? 'twitter' : p));

const ayrsharePayload = {
  post: variantLinkedIn || variantX || variantInstagram,
  platforms: ayrPlatforms,
  scheduleDate: publishDate.toISOString(),
  mediaUrls: mediaUrls.length > 0 ? mediaUrls : undefined,
  postType: mediaUrls.length > 0 ? 'image' : 'text'
};

if (variantX) ayrsharePayload.twitter = variantX;
if (variantInstagram) ayrsharePayload.instagram = variantInstagram;
if (variantLinkedIn) ayrsharePayload.linkedin = variantLinkedIn;

return {
  json: {
    record_id: recordId,
    has_error: false,
    ayrshare_payload: ayrsharePayload,
    publish_at: publishDate.toISOString()
  }
};
